"""Current review biomass support by physical comparison/year; no paper edits."""
from pathlib import Path
import pandas as pd
R=Path(__file__).resolve().parents[2];B=R/'outputs/integrated_review_20261103';O=R/'outputs/biomass_policy_review_20261103';O.mkdir(exist_ok=True)
a=pd.read_csv(B/'annual_values.csv');a=a[a.Resp.eq('Bio')].copy();v=pd.read_csv(B/'visit_biomass_support.csv');v=v[v.series_id.isin(a.series_id)]
v['direct']=v.basis.isin(['same_count_record','same_site_zone_date_sizes','same_site_near_date_sizes']);v['borrowed']=v.basis.str.startswith('calibrated_',na=False);v['unsupported']=~v.biomass_supported
s=v.groupby(['series_id','year']).agg(visits=('basis','size'),direct_visits=('direct','sum'),borrowed_visits=('borrowed','sum'),unsupported_visits=('unsupported','sum'),size_sites=('site','nunique')).reset_index();a=a.merge(s,on=['series_id','year'],how='left',validate='one_to_one');a['supported_borrowed']=a.response_supported&a.borrowed_visits.gt(0);a['support_status']='unavailable';a.loc[a.response_supported,'support_status']='direct_or_observed';a.loc[a.response_supported&a.borrowed_visits.gt(0),'support_status']='includes_borrowed_sizes';a.to_csv(O/'comparison_year_support.csv',index=False)
h=a.groupby(['series_id','MPA','Source','Taxa']).agg(candidate_years=('year','size'),supported_years=('response_supported','sum'),borrowed_years=('borrowed_visits',lambda z:int((z>0).sum())),supported_borrowed_years=('supported_borrowed','sum'),unsupported_visits=('unsupported_visits','sum'),first_year=('year','min'),last_year=('year','max')).reset_index();h['unsupported_years']=h.candidate_years-h.supported_years;h.to_csv(O/'comparison_support.csv',index=False)
print('histories',len(h),'candidate years',len(a),'supported',a.response_supported.sum(),'borrowed flagged',int((a.borrowed_visits>0).sum()));print(a.groupby('Source').agg(candidate=('year','size'),supported=('response_supported','sum'),borrowed_years=('borrowed_visits',lambda z:int((z>0).sum())),supported_borrowed_years=('supported_borrowed','sum')).to_string())
